#include <iostream>
#include <memory>
#include <vector>
struct Adjustment {
    virtual ~Adjustment() = default;
    virtual int apply(int value) const = 0;
};
struct Add final : Adjustment {
    int delta;
    explicit Add(int n) : delta(n) {}
    int apply(int n) const override { return n + delta; }
};
struct Scale final : Adjustment {
    int factor;
    explicit Scale(int n) : factor(n) {}
    int apply(int n) const override { return n * factor; }
};
using Pipeline = std::vector<std::unique_ptr<Adjustment>>;
int apply_all(const Pipeline& steps, int value) {
    // TODO: applica ogni stadio, in ordine, senza copiare gli owner.
    for (const auto& step : steps) {
        value = step->apply(value);
    }
    return value;
}
int main() {
    int value=0, delta=0, factor=0;
    std::cin >> value >> delta >> factor;
    Pipeline steps;
    steps.push_back(std::make_unique<Add>(delta));
    steps.push_back(std::make_unique<Scale>(factor));
    std::cout << apply_all(steps, value) << ' '
              << apply_all(Pipeline{}, value) << '\n';
}

